/** SVG de un icono, listo para insertar. Hereda `color` por CSS. */
export function ico(nombre, cls = '') {
  const d = D[nombre];
  if (!d) return '';
  return `<svg class="${cls}" viewBox="0 0 512 512" fill="currentColor" aria-hidden="true">${d}</svg>`;
}

export const NOMBRES = Object.keys(D);
